export function createUnitCopyUI({e,api,ui,link}){
 const hidden=(n,v)=>'<input type="hidden" name="'+n+'" value="'+e(v??'')+'">';
 const fileNames=files=>(files||[]).length?'<small>Files: '+files.map(f=>e(f.name)).join(' · ')+'</small>':'<small>No attached files</small>';
 const sourceLink=(label,p)=>'<a href="#/classroom?'+new URLSearchParams(p)+'" target="_blank" rel="noopener">'+e(label)+' ↗</a>';
 async function copyPage(params){const d=await api('unit-copy-preview?'+new URLSearchParams({unitId:params.get('copyUnit'),...(params.get('targetClassId')?{targetClassId:params.get('targetClassId')}:{})})),u=d.source;return '<p>'+link('← Source unit',{class:u.classId,tab:'units',unit:u.id})+'</p><div class="learning-section-title"><h2>Copy a teaching unit</h2><span class="vle-status">Preview</span><button type="button" class="btn" data-unit-copy-refresh>Refresh preview</button></div><section class="vle-panel"><h3>'+e(u.title)+'</h3><p>'+e(u.className)+' · '+d.assignments.length+' tasks</p><details><summary>Review source material</summary><p class="vle-prose">'+e(u.description)+'</p>'+fileNames(u.files)+'</details></section><label class="vle-field">Destination classroom<select id="unit-copy-target" aria-label="Destination classroom"><option value="">Choose a classroom…</option>'+d.classes.map(c=>'<option value="'+e(c.id)+'" '+(d.target?.id===c.id?'selected':'')+'>'+e(c.name)+(c.id===u.classId?' · Same class':'')+'</option>').join('')+'</select></label>'+(d.target?'<form data-vle="unit-copy" class="vle-panel">'+hidden('unitId',u.id)+hidden('targetClassId',d.target.id)+hidden('snapshot',d.snapshot)+hidden('operationId',crypto.randomUUID())+'<label class="vle-field">Copied unit title<input name="title" maxlength="160" value="'+e(u.title)+'" required></label><p class="vle-note">The copied unit and its selected tasks start as private drafts in '+e(d.target.name)+'. Review them and choose new dates before publishing.</p><p>Teaching material, questions, marking criteria and selected task files are copied. Student work, grades and conversations stay with their original class. Original deadlines, release dates, student selections and prerequisites are cleared.</p><label class="community-check"><input type="checkbox" name="includeFiles" checked> Include unit attachments ('+u.files.length+')</label><div class="learning-section-title"><h3>Choose tasks</h3><div><button type="button" class="text-button" data-copy-select="all">Select all</button> · <button type="button" class="text-button" data-copy-select="none">Clear all</button></div></div><div class="unit-copy-tasks">'+d.assignments.map((a,i)=>(i===6?'<details class="updates-more"><summary>Show '+(d.assignments.length-6)+' more tasks</summary><div class="unit-copy-tasks">':'')+'<label class="unit-copy-task"><input type="checkbox" data-copy-task="'+e(a.id)+'" checked><span><strong>'+e(a.title)+'</strong><small>'+e(a.kind==='quiz'?'Quiz · '+a.questions+' questions':'Assignment')+' · '+a.maximum+' points · '+e(a.status)+(a.due?' · Old due date '+e(a.due):'')+'</small>'+fileNames(a.files)+sourceLink('View source task',{class:u.classId,assignment:a.id})+'</span></label>'+(i===d.assignments.length-1&&d.assignments.length>6?'</div></details>':'')).join('')+(!d.assignments.length?'<p>This is a reading/material unit. Its material will be copied without assignments.</p>':'')+'</div><div class="vle-actions"><span data-copy-count>'+d.assignments.length+' tasks selected</span><button type="submit" class="btn primary">Create draft copy →</button></div></form>':'<p class="learning-empty">Choose a destination to review and create the draft copy.</p>');}
 async function publishPage(params){const d=await api('unit-publish-preview?id='+encodeURIComponent(params.get('publishUnit'))),u=d.unit;return '<p>'+link('← Edit unit material & sequence',{class:u.classId,tab:'units',unit:u.id})+'</p><div class="learning-section-title"><h2>Review & publish unit</h2><span class="vle-status">Private draft</span><button type="button" class="btn" data-unit-copy-refresh>Refresh review</button></div><section class="vle-panel"><h3>'+e(u.title)+'</h3><p>'+e(d.className)+'</p><details><summary>Review teaching material</summary><p class="vle-prose">'+e(u.description)+'</p>'+fileNames(u.files)+'</details><p>'+(u.releaseAt?'Scheduled release: '+e(new Date(u.releaseAt).toLocaleString('en-GB',{timeZone:'Asia/Tashkent'}))+' (Tashkent).':'Available after publication, subject to prerequisites.')+'</p>'+ (u.prerequisiteId?'<p>A prerequisite unit must be completed first.</p>':'')+'</section><form data-vle="unit-publish" class="vle-panel">'+hidden('id',u.id)+hidden('snapshot',d.snapshot)+'<h3>Choose the tasks to make available</h3><p>Set deadlines here before publishing. Save your draft plan to return later, or publish when ready. Unchecked tasks stay private and keep their current dates.</p>'+(d.assignments.some(a=>a.status==='draft')?'<div class="vle-actions"><label class="vle-field">Date for selected drafts<input type="date" data-unit-bulk-date></label><button type="button" class="btn" data-unit-apply-date>Apply date</button><button type="button" class="btn" data-unit-clear-dates>Clear selected dates</button></div><p class="sr-only" aria-live="polite" data-unit-date-status></p>':'')+'<div class="unit-copy-tasks">'+d.assignments.map((a,i)=>(i===6?'<details class="updates-more"><summary>Show '+(d.assignments.length-6)+' more tasks</summary><div class="unit-copy-tasks">':'')+'<div class="unit-copy-task"><input type="checkbox" aria-label="Publish '+e(a.title)+'" data-publish-task="'+e(a.id)+'" '+(a.status==='published'||!u.selectedIds||u.selectedIds.includes(a.id)?'checked':'')+' '+(a.status==='published'?'disabled':'')+'><span><strong>'+e(a.title)+'</strong><small>'+e(a.kind==='quiz'?'Quiz · '+a.questions+' questions':'Assignment')+' · '+a.maximum+' points · '+(a.status==='draft'?'Set deadline below':(a.due?'Due '+e(a.due):'No deadline set'))+'</small>'+(a.status==='draft'?'<label class="vle-field">Deadline · '+e(a.title)+'<input type="date" data-unit-deadline="'+e(a.id)+'" value="'+e(a.due||'')+'"></label>':'')+fileNames(a.files)+(a.status==='published'?'<small>Already assigned inside this draft unit; becomes available with the unit.</small>':'')+sourceLink('Review / edit task',a.kind==='quiz'&&a.status==='draft'?{class:u.classId,quizEditor:a.id}:{class:u.classId,assignment:a.id})+'</span></div>'+(i===d.assignments.length-1&&d.assignments.length>6?'</div></details>':'')).join('')+(!d.assignments.length?'<p>This unit contains reading or teaching material only.</p>':'')+'</div><p class="vle-note">Publishing makes the unit material and selected tasks available when their release and prerequisite conditions are met.</p><div class="vle-actions"><button type="submit" name="intent" value="save-draft" class="btn">Save draft plan</button><button type="submit" name="intent" value="publish" class="btn primary">Publish unit</button></div></form>';}
 function bind(root){
 const deadlineInputs=[...root.querySelectorAll('[data-unit-deadline]')],taskChecks=[...root.querySelectorAll('[data-publish-task]')];
 const selectedDates=()=>deadlineInputs.filter(el=>taskChecks.some(x=>x.dataset.publishTask===el.dataset.unitDeadline&&x.checked));
 const syncDates=()=>{for(const el of deadlineInputs)el.disabled=!taskChecks.some(x=>x.dataset.publishTask===el.dataset.unitDeadline&&x.checked);};
 taskChecks.forEach(x=>x.addEventListener('change',syncDates));syncDates();
 const applyDate=clear=>{const input=root.querySelector('[data-unit-bulk-date]');if(!clear&&!input.value){input.reportValidity();ui.toast('Choose a date first.');return;}const chosen=selectedDates();chosen.forEach(el=>el.value=clear?'':input.value);if(chosen.length)ui.dirty(true);const message=(clear?'Cleared deadlines for ':'Updated deadlines for ')+chosen.length+' selected draft '+(chosen.length===1?'task':'tasks')+'. Dates save with Save draft plan or Publish unit.';const status=root.querySelector('[data-unit-date-status]');if(status)status.textContent=message;ui.toast(message);};
 root.querySelector('[data-unit-apply-date]')?.addEventListener('click',()=>applyDate(false));root.querySelector('[data-unit-clear-dates]')?.addEventListener('click',()=>applyDate(true));
root.querySelector('[data-unit-copy-refresh]')?.addEventListener('click',()=>{if(ui.isDirty?.()&&!confirm('Refresh and reset these unsaved choices?'))return;ui.dirty(false);ui.render();});const target=root.querySelector('#unit-copy-target');if(target){const previous=target.value;target.addEventListener('change',ev=>{if(ui.isDirty?.()&&!confirm('Discard these unsaved copy choices?')){target.value=previous;return;}ui.dirty(false);const p=new URLSearchParams(location.hash.split('?')[1]);p.set('targetClassId',ev.target.value);location.hash='/classroom?'+p;});}const count=()=>{const el=root.querySelector('[data-copy-count]');if(el)el.textContent=root.querySelectorAll('[data-copy-task]:checked').length+' tasks selected';};root.querySelectorAll('[data-copy-task]').forEach(b=>b.addEventListener('change',count));root.querySelectorAll('[data-copy-select]').forEach(b=>b.addEventListener('click',()=>{root.querySelectorAll('[data-copy-task]').forEach(x=>x.checked=b.dataset.copySelect==='all');count();ui.dirty(true);}));}
 function readAction(action,d,f,intent){if(action==='unit-copy'){d.includeFiles=f.elements.includeFiles.checked;d.assignmentIds=[...f.querySelectorAll('[data-copy-task]:checked')].map(x=>x.dataset.copyTask);}if(action==='unit-publish'){d.mode=intent==='save-draft'?'save-draft':'publish';d.assignmentIds=[...f.querySelectorAll('[data-publish-task]:checked')].map(x=>x.dataset.publishTask);d.deadlines=[...f.querySelectorAll('[data-unit-deadline]')].filter(x=>d.assignmentIds.includes(x.dataset.unitDeadline)).map(x=>({id:x.dataset.unitDeadline,due:x.value}));}}
 return{copyPage,publishPage,bind,readAction};
}

